import os
import torch


class Config:
    # -------------------------------------------------------------------------
    # Directory and File Paths
    # -------------------------------------------------------------------------
    # Read-only input directories
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # Metadata file paths (generated by the provided script)
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train_metadata.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val_metadata.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test_metadata.csv")

    # Geometry file directories
    TRAIN_GEOMETRY_DIR = os.path.join(INPUT_DIR, "train")
    TEST_GEOMETRY_DIR = os.path.join(INPUT_DIR, "test")

    # Working directory for artifacts (Cache, Checkpoints)
    # Using a specific subdirectory to keep things organized
    WORKING_DIR = "./working/idea_19"
    CACHE_DIR = os.path.join(WORKING_DIR, "cache")
    CHECKPOINT_DIR = os.path.join(WORKING_DIR, "checkpoints")

    # Submission directory
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # Create necessary writable directories
    os.makedirs(CACHE_DIR, exist_ok=True)
    os.makedirs(CHECKPOINT_DIR, exist_ok=True)
    os.makedirs(SUBMISSION_DIR, exist_ok=True)

    # Cache file paths for processed graph data
    # Using .npz for efficient storage of graph dictionaries
    TRAIN_GRAPH_CACHE = os.path.join(CACHE_DIR, "train_graphs.npz")
    VAL_GRAPH_CACHE = os.path.join(CACHE_DIR, "val_graphs.npz")
    TEST_GRAPH_CACHE = os.path.join(CACHE_DIR, "test_graphs.npz")

    # Scaler cache path
    TARGET_SCALER_CACHE = os.path.join(CACHE_DIR, "target_scaler.npz")

    # -------------------------------------------------------------------------
    # Data Processing Hyperparameters
    # -------------------------------------------------------------------------
    # Cutoff radius for neighbor search (Periodic Boundary Conditions)
    CUTOFF_RADIUS = 5.0  # Angstroms

    # Maximum number of neighbors to consider per atom (for efficiency)
    MAX_NEIGHBORS = 12

    # RBF Expansion settings for edge features
    RBF_BINS = 80
    RBF_MIN = 0.0
    RBF_MAX = 5.0  # Matches cutoff

    # Debugging / Development
    # Set to a small integer (e.g., 100) to train on a subset for testing pipeline
    # Set to None for full training
    DATA_SAMPLE_SIZE = None

    # -------------------------------------------------------------------------
    # Model Architecture Hyperparameters (SR-CGN-DP)
    # -------------------------------------------------------------------------
    ATOM_EMBEDDING_DIM = 192
    NUM_LAYERS = 4  # Number of CGCNN layers
    DROPOUT_RATE = 0.1  # Dropout applied within interaction blocks

    # -------------------------------------------------------------------------
    # Training Hyperparameters
    # -------------------------------------------------------------------------
    BATCH_SIZE = 48
    LEARNING_RATE = 1e-3  # Initial learning rate
    WEIGHT_DECAY = 1e-4  # Regularization for AdamW
    NUM_EPOCHS = 120  # Total training epochs
    EARLY_STOPPING_PATIENCE = 20

    # -------------------------------------------------------------------------
    # System & Reproducibility
    # -------------------------------------------------------------------------
    SEED = 42
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 4  # Number of subprocesses for data loading
